    if list(raw_op) != ["op", "now"]:
        fail(EXIT_INPUT, "INPUT")
    return ("br", parse_metric_num(raw_op["now"]))

if name == "ru":
    # 不可用时长查询：精确键序 op,id,now（键须按此序出现）；id 为非空
    # UTF-8 串（未知 id 留执行期判 BACKEND），now 为 0..10^9 非 bool
    # 整数，纳入共用非递减时钟。
    if list(raw_op) != ["op", "id", "now"]:
