    return ("hm", parse_backend_id(raw_op["id"]))

if name == "fm":
    # 故障演练统计查询：精确键集 op,id，只读；非法 id 在解析期判 INPUT，
    # 未知 id 在执行期判 BACKEND。
    if keys != {"op", "id"}:
        fail(EXIT_INPUT, "INPUT")
    return ("fm", parse_backend_id(raw_op["id"]))

if name == "fh":
    # 故障统计分钟历史：精确键集 op,id,from,to,now，只读；数值与关系
