    if list(raw_op) != ["op", "w", "hi", "lo", "n", "now"]:
        fail(EXIT_INPUT, "INPUT")
    w = parse_metric_num(raw_op["w"])
    hi = raw_op["hi"]
    # bool 是 int 的子类，必须显式排除。
    if (
        not isinstance(hi, int)
        or isinstance(hi, bool)
        or not 1 <= hi <= 10 ** 18
    ):
        fail(EXIT_INPUT, "INPUT")
    lo = raw_op["lo"]
    if (
