            fail(EXIT_INPUT, "INPUT")
        times.append(at)
    return (
        "ft",
        parse_key(raw_op["key"]),
        times,
        parse_fault_num(raw_op["timeout"]),
        parse_attempt_max(raw_op["max"]),
        now,
